def make_list_tree(depth):
    if depth == 0:
        return []
    return [make_list_tree(depth - 1), make_list_tree(depth - 1)]


def make_tuple_tree(depth):
    if depth == 0:
        return ()
    return (make_tuple_tree(depth - 1), make_tuple_tree(depth - 1))


