import sys
import time


def visit(depth, values):
    total = 0
    for value in values:
        total += value
    if depth == 0:
        return total
    return total + visit(depth - 1, values) + visit(depth - 1, values)


def visit_sum(depth, values):
    total = sum(values)
    if depth == 0:
        return total
    return total + visit_sum(depth - 1, values) + visit_sum(depth - 1, values)


def bench():
